          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\n */\n//(1)==============================================================\nimport java.util.*;\nimport java.io.*;\n\npublic class MyList {\n\n    Node head, tail;\n\n    MyList() {\n        head = tail = null;\n    }\n\n    boolean isEmpty() {\n        return (head == null);\n    }\n\n    void clear() {\n        head = tail = null;\n    }\n\n    void fvisit(Node p, RandomAccessFile f) throws Exception {\n        if (p != null) {\n            f.writeBytes(p.info + \" \");\n        }\n    }\n\n    void ftraverse(RandomAccessFile f) throws Exception {\n        Node p = head;\n        while (p != null) {\n            fvisit(p, f); // You will use this statement to write information of the node p to the file\n            p = p.next;\n        }\n        f.writeBytes(\"\\r\\n\");\n    }\n\n    void loadData(int k) { //do not edit this function\n        String[] a = Lib.readLineToStrArray(\"data.txt\", k);\n        int[] b = Lib.readLineToIntArray(\"data.txt\", k + 1);\n        int[] c = Lib.readLineToIntArray(\"data.txt\", k + 2);\n        int n = a.length;\n        for (int i = 0; i < n; i++) {\n            addLast(a[i], b[i], c[i]);\n        }\n    }\n\n//===========================================================================\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\n//===========================================================================\n/* \n   Khong su dung tieng Viet co dau de viet ghi chu.\n   Neu dung khi chay truc tiep se bao loi va nhan 0 diem\n     */\n    void addLast(String xPlace, int xWeight, int xColor) { //f1\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        if (xWeight == 6) {\n            return;\n        }\n        Node node = new Node(new Lion(xPlace, xWeight, xColor));\n        if (isEmpty()) {\n            head = tail = node;\n        } else {\n            tail.next = node;\n            tail = node;\n        }\n        //---------------------------------------------------------\n    }\n    \n    //You can add new methods/functions here\n\n    \n    \n    \n    //==================================================================\n    //You do not need to edit this function. Your task is to complete the addLast function above only.\n    void f1() throws Exception {\n        clear();\n        loadData(1);\n        String fname = \"f1.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        f.close();\n    }\n\n//==================================================================\n    void f2() throws Exception {\n        clear();\n        loadData(5);\n        String fname = \"f2.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        Node a = new Node(new Lion(\"A\", 4, 1));\n        Node b = new Node(new Lion(\"B\", 7, 2));\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        Your task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        // b becomes the 2nd node (right after head), a becomes the 3rd node (right after b)\n        b.next = head.next;\n        head.next = b;\n        a.next = b.next;\n        b.next = a;\n        //------------------------------------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n//==================================================================\n    void f3() throws Exception {\n        clear();\n        loadData(9);\n        String fname = \"f3.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        Your task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        // delete the 4th element (1-indexed) of the original list\n        if (head != null) {\n            if (head.next != null && head.next.next != null && head.next.next.next != null) {\n                Node prev = head.next.next; // 3rd node\n                Node target = prev.next;    // 4th node\n                prev.next = target.next;\n                if (target == tail) tail = prev;\n            }\n        }\n        //------------------------------------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n//==================================================================\n    void f4() throws Exception {\n        clear();\n        loadData(13);\n        String fname = \"f4.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        Your task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        int count = 0;\n        Node p = head;\n        while (p != null) {\n            count++;\n            p = p.next;\n        }\n        f.writeBytes(count + \"\\r\\n\");\n        //------------------------------------------------------------------------------------\n        f.close();\n    }\n    \n//==================================================================\n    void f5() throws Exception {\n        clear();\n        loadData(17);\n        String fname = \"f5.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        Your task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        // sort descending by color (selection sort, swap info only)\n        Node a = head;\n        while (a != null) {\n            Node maxNode = a;\n            Node b = a.next;\n            while (b != null) {\n                if (b.info.color > maxNode.info.color) maxNode = b;\n                b = b.next;\n            }\n            if (maxNode != a) {\n                Lion tmp = a.info;\n                a.info = maxNode.info;\n                maxNode.info = tmp;\n            }\n            a = a.next;\n        }\n\n        //------------------------------------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n}\n",
